<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { computed } from 'vue';
const props = defineProps({ incidents: Array, sites: Array, playbooks: Array, alerts: Array });
const form = useForm({ title: '', site_id: '', asset_id: '', playbook_version_id: '', started_at: new Date().toISOString().slice(0,16), alert_ids: [], improvised_notes: '' });
const assets = computed(() => props.sites.find(site => site.id == form.site_id)?.assets || []);
const save = () => form.post(route('incidents.store'));
</script>
<template><Head title="Incidents" /><AuthenticatedLayout><template #header><div><h1 class="text-2xl font-semibold">Incidents</h1><p class="text-sm text-slate-500">One record for alerts, procedures, actions, and resolution.</p></div></template><div class="mx-auto grid max-w-7xl gap-6 px-4 py-8 lg:grid-cols-[3fr_2fr]"><section class="space-y-3"><Link v-for="incident in incidents" :key="incident.id" :href="route('incidents.show', incident.id)" class="block rounded-xl border bg-white p-5 shadow-sm hover:border-teal-300"><div class="flex justify-between gap-4"><div><h2 class="font-semibold">{{ incident.title }}</h2><p class="mt-1 text-sm text-slate-600">{{ incident.site?.name || 'Organization-wide' }}<span v-if="incident.asset"> / {{ incident.asset.name }}</span></p></div><span class="h-fit rounded-full px-2 py-1 text-xs font-semibold uppercase" :class="incident.status === 'open' ? 'bg-red-100 text-red-800' : 'bg-emerald-100 text-emerald-800'">{{ incident.status }}</span></div><p class="mt-3 text-xs text-slate-500">Started {{ new Date(incident.started_at).toLocaleString() }} / {{ incident.alerts_count }} alerts / {{ incident.actions_count }} actions</p></Link><p v-if="!incidents.length" class="rounded-xl border bg-white py-12 text-center text-sm text-slate-500">No incident records.</p></section><form @submit.prevent="save" class="h-fit rounded-xl border bg-white p-6 shadow-sm"><h2 class="font-semibold">Open incident</h2><label class="mt-4 block text-sm font-medium">Incident title</label><input v-model="form.title" required class="mt-1 w-full rounded-lg border-slate-300" /><label class="mt-3 block text-sm font-medium">Started at</label><input v-model="form.started_at" type="datetime-local" required class="mt-1 w-full rounded-lg border-slate-300" /><label class="mt-3 block text-sm font-medium">Site</label><select v-model="form.site_id" class="mt-1 w-full rounded-lg border-slate-300"><option value="">Organization-wide</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select><label class="mt-3 block text-sm font-medium">Asset</label><select v-model="form.asset_id" class="mt-1 w-full rounded-lg border-slate-300"><option value="">No specific asset</option><option v-for="asset in assets" :key="asset.id" :value="asset.id">{{ asset.name }}</option></select><label class="mt-3 block text-sm font-medium">Playbook</label><select v-model="form.playbook_version_id" class="mt-1 w-full rounded-lg border-slate-300"><option value="">No playbook / improvised response</option><option v-for="playbook in playbooks" :key="playbook.id" :value="playbook.current.id">{{ playbook.title }} (v{{ playbook.current.version }})</option></select><label class="mt-3 block text-sm font-medium">Related alerts</label><div class="mt-2 max-h-32 space-y-2 overflow-auto rounded-lg border p-3"><label v-for="alert in alerts" :key="alert.id" class="flex gap-2 text-sm"><input v-model="form.alert_ids" type="checkbox" :value="alert.id" class="rounded border-slate-300" />{{ alert.title }} ({{ alert.severity }})</label><p v-if="!alerts.length" class="text-xs text-slate-500">No open alerts.</p></div><label class="mt-3 block text-sm font-medium">Improvised response notes</label><textarea v-model="form.improvised_notes" :required="!form.playbook_version_id" rows="3" class="mt-1 w-full rounded-lg border-slate-300"></textarea><button class="mt-4 w-full rounded-lg bg-red-700 px-4 py-2 text-sm font-semibold text-white">Open incident record</button></form></div></AuthenticatedLayout></template>
